/// The rounding mode values of [`Desc::rmode`]: `FPROUNDING_TIEEVEN`, `_NEGINF`, `_POSINF`,
/// `_ZERO`, `_TIEAWAY`, and the mode in FPCR.
pub(super) const RN: u32 = 0;
pub(super) const RM: u32 = 1;
pub(super) const RP: u32 = 2;
pub(super) const RZ: u32 = 3;
pub(super) const RA: u32 = 4;
pub(super) const RF: u32 = crate::tcg::vec_helper::RMODE_FPCR;

/// The element size checks QEMU does before `fp_access_check()`.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(super) enum Chk {
    None,
    /// `do_gvec_fn*`: no 64 bit elements in a 64 bit vector.
    Fn,
    /// `do_gvec_fn*_no64`: no 64 bit elements.
    No64,
    /// `_hs`, `_no8_no64`: 16 or 32 bit elements only.
    Hs,
}

/// The ID register features some instructions need.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(super) enum Feat {
    None,
    Fp16,
    Rdm,
    DotProd,
    Aes,
    Pmull,
    Sha1,
    Sha256,
}

/// The FMOV forms between a general and a SIMD register.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(super) enum Mov {
    /// Hd from Wn.
    Hx,
    /// Sd from Wn.
    Sw,
    /// Dd from Xn.
    Dx,
    /// Vd.D[1] from Xn.
    Ux,
    /// Wd from Hn.
    Xh,
    /// Wd from Sn.
    Ws,
    /// Xd from Dn.
    Xd,
    /// Xd from Vn.D[1].
    Xu,
}

fn chk(c: Chk, q: i32, esz: i32) -> bool {
    match c {
        Chk::None => true,
        Chk::Fn => !(q == 0 && esz == 3),
        Chk::No64 => esz != 3,
        Chk::Hs => esz == 1 || esz == 2,
    }
}

fn oprsz(q: i32) -> usize {
    if q != 0 { 16 } else { 8 }
}

/// `decode_esz_idx()`: the element size and index of the imm5 field of the copy instructions.
fn decode_esz_idx(imm: i32) -> Option<(i32, i32)> {
    let esz = (imm as u32).trailing_zeros() as i32;
    if esz <= 3 { Some((esz, imm >> (esz + 1))) } else { None }
}

/// `asimd_imm_const()`: AdvSIMDExpandImm, with the inversion of the op=1 forms.
pub(super) fn asimd_imm_const(imm: u32, cmode: i32, op: i32) -> u64 {
    let mut imm = imm;
    match cmode {
        0 | 1 => {}
        2 | 3 => imm <<= 8,
        4 | 5 => imm <<= 16,
        6 | 7 => imm <<= 24,
        8 | 9 => imm |= imm << 16,
        10 | 11 => imm = (imm << 8) | (imm << 24),
        12 => imm = (imm << 8) | 0xff,
        13 => imm = (imm << 16) | 0xffff,
        14 => {
            if op != 0 {
                let mut imm64 = 0u64;
                for n in 0..8 {
                    if imm & (1 << n) != 0 {
                        imm64 |= 0xff << (n * 8);
                    }
                }
                return imm64;
            }
            imm |= (imm << 8) | (imm << 16) | (imm << 24);
        }
        _ => {
            if op != 0 {
                let mut imm64 = u64::from(imm & 0x3f) << 48;
                if imm & 0x80 != 0 {
                    imm64 |= 0x8000_0000_0000_0000;
                }
                if imm & 0x40 != 0 {
                    imm64 |= 0x3fc0_0000_0000_0000;
                } else {
                    imm64 |= 0x4000_0000_0000_0000;
                }
                return imm64;
            }
            imm = ((imm & 0x80) << 24)
                | ((imm & 0x3f) << 19)
                | if imm & 0x40 != 0 { 0x1f << 25 } else { 1 << 30 };
        }
    }
    if op != 0 {
        imm = !imm;
    }
    u64::from(imm) * 0x0000_0001_0000_0001
}

/// Replicate the low `8 << esz` bits of a value to 64 bits.
fn dup_const(esz: i32, v: u64) -> u64 {
    match esz {
        0 => (v & 0xff) * 0x0101_0101_0101_0101,
        1 => (v & 0xffff) * 0x0001_0001_0001_0001,
        2 => (v & 0xffff_ffff) * 0x0000_0001_0000_0001,
        _ => v,
    }
}

impl S<'_, '_> {
    /// `fp_access_check()`: raise the FP access trap if CPACR_EL1.FPEN says so. Returns true
    /// if the instruction should be translated.
    pub(super) fn fp_access_check(&mut self) -> bool {
        if self.d.fp_excp_el == 0 {
            return true;
        }
        self.update_pc(0);
        let env = self.env();
        let e = self.c32(EXCP_UDEF);
        let syn = self.c32(syn_a64_fp_access_trap(1, 0xe) as i32);
        let el = self.c32(self.d.fp_excp_el as i32);
        self.call(
            &helpers::EXCEPTION_WITH_SYNDROME_EL,
            None,
            &[env.into(), e.into(), syn.into(), el.into()],
        );
        self.b.is_jmp = DisasJumpType::NoReturn;
        false
    }

    fn has(&self, f: Feat) -> bool {
        let x = self.feat();
        match f {
            Feat::None => true,
            Feat::Fp16 => x.fp16,
            Feat::Rdm => x.rdm,
            Feat::DotProd => x.dotprod,
            Feat::Aes => x.aes,
            Feat::Pmull => x.pmull,
            Feat::Sha1 => x.sha1,
            Feat::Sha256 => x.sha256,
        }
    }

    /// `fp_access_check_vector_hsd()` and `_scalar_hsd()` (with `q` set) without the access
    /// check: whether the element size is allocated.
    fn hsd(&self, esz: i32, q: bool) -> bool {
        match esz {
            3 => q,
            2 => true,
            1 => self.feat().fp16,
            _ => false,
        }
    }

    fn vcall(&mut self, def: &Def, r: [i32; 4], desc: Desc) {
        let env = self.env();
        let regs = self.c32(Regs::pack(r[0], r[1], r[2], r[3]) as i32);
        let d = self.c32(desc.pack() as i32);
        self.call(def, None, &[env.into(), regs.into(), d.into()]);
    }

    /// Translate a helper call: false if not allocated, the access check, then the call.
    fn emit(&mut self, ok: bool, def: &Def, r: [i32; 4], desc: Desc) -> bool {
        if !ok {
            return false;
        }
        if self.fp_access_check() {
            self.vcall(def, r, desc);
        }
        true
    }

    // Element access.

    fn elem_off(reg: i32, idx: i32, esz: i32) -> i64 {
        (vreg_off(reg as usize) + ((idx as usize) << esz)) as i64
    }

    /// `read_vec_element()`: element `idx` of `reg`, zero or sign extended.
    fn read_elem(&mut self, reg: i32, idx: i32, esz: i32, signed: bool) -> TempI64 {
        let t = self.new64();
        let env = self.env();
        let off = Self::elem_off(reg, idx, esz);
        let f = self.f();
        match (esz, signed) {
            (0, false) => f.gen_ld8u_i64(t, env, off),
            (0, true) => f.gen_ld8s_i64(t, env, off),
            (1, false) => f.gen_ld16u_i64(t, env, off),
            (1, true) => f.gen_ld16s_i64(t, env, off),
            (2, false) => f.gen_ld32u_i64(t, env, off),
            (2, true) => f.gen_ld32s_i64(t, env, off),
            _ => f.gen_ld_i64(t, env, off),
        }
        t
    }

    /// `write_vec_element()`.
    fn write_elem(&mut self, reg: i32, idx: i32, esz: i32, t: TempI64) {
        let env = self.env();
        let off = Self::elem_off(reg, idx, esz);
        let f = self.f();
        match esz {
            0 => f.gen_st8_i64(t, env, off),
            1 => f.gen_st16_i64(t, env, off),
            2 => f.gen_st32_i64(t, env, off),
            _ => f.gen_st_i64(t, env, off),
        }
    }

    /// Write the two halves of a register; `hi` None writes zero.
    fn write_vreg(&mut self, reg: i32, lo: TempI64, hi: Option<TempI64>) {
        let off = vreg_off(reg as usize);
        self.st_env64(lo, off);
        let hi = match hi {
            Some(h) => h,
            None => self.c64(0),
        };
        self.st_env64(hi, off + 8);
        self.clear_sve(reg);
    }

    /// The part of `clear_vec_high()` above 128 bits: with SVE, zero the bytes of the Z
    /// register from 16 up to the vector length.
    pub(super) fn clear_sve(&mut self, reg: i32) {
        let vl = self.d.vl as usize;
        if !self.feat().sve || vl <= 16 {
            return;
        }
        let z = self.c64(0);
        let off = vreg_off(reg as usize);
        for o in (16..vl).step_by(8) {
            self.st_env64(z, off + o);
        }
    }

    /// `write_fp_dreg()`: the low 64 bits, clearing the rest.
    fn write_fp_dreg(&mut self, reg: i32, t: TempI64) {
        self.write_vreg(reg, t, None);
    }

    /// `clear_vec_high()` for a 64 bit write.
    fn clear_high(&mut self, reg: i32) {
        let z = self.c64(0);
        self.st_env64(z, vreg_off(reg as usize) + 8);
        self.clear_sve(reg);
    }

    /// Replicate the low element of `t` across 64 bits, in place.
    fn dup64(&mut self, t: TempI64, esz: i32) {
        let f = self.f();
        match esz {
            0 => {
                f.gen_ext8u_i64(t, t);
                f.gen_muli_i64(t, t, 0x0101_0101_0101_0101);
            }
            1 => {
                f.gen_ext16u_i64(t, t);
                f.gen_muli_i64(t, t, 0x0001_0001_0001_0001);
            }
            2 => {
                f.gen_ext32u_i64(t, t);
                f.gen_muli_i64(t, t, 0x0000_0001_0000_0001);
            }
            _ => {}
        }
    }

    /// Write a replicated 64 bit value to the low half, and to the high half if `q`.
    fn write_dup(&mut self, reg: i32, t: TempI64, q: bool) {
        self.write_vreg(reg, t, if q { Some(t) } else { None });
    }

    // Integer three registers.

    pub(super) fn v3(&mut self, a: &arg_qrrr_e, op: u32, c: Chk, f: Feat) -> bool {
        let ok = self.has(f) && chk(c, a.q, a.esz);
        self.emit(ok, &NEON, [a.rd, a.rn, a.rm, 0], Desc::new(op, a.esz, oprsz(a.q)))
    }

    /// SUQADD and USQADD: the accumulator is Rd and the source Rm.
    pub(super) fn v3acc(&mut self, a: &arg_qrrr_e, op: u32) -> bool {
        let ok = chk(Chk::Fn, a.q, a.esz);
        self.emit(ok, &NEON, [a.rd, a.rm, 0, 0], Desc::new(op, a.esz, oprsz(a.q)))
    }

    pub(super) fn s3(&mut self, a: &arg_rrr_e, op: u32, c: Chk, f: Feat) -> bool {
        let ok = self.has(f) && chk(c, 1, a.esz);
        self.emit(ok, &NEON, [a.rd, a.rn, a.rm, 0], Desc::new(op, a.esz, 1 << a.esz))
    }

    pub(super) fn s3acc(&mut self, a: &arg_rrr_e, op: u32) -> bool {
        self.emit(true, &NEON, [a.rd, a.rm, 0, 0], Desc::new(op, a.esz, 1 << a.esz))
    }

    // Integer two registers.

    pub(super) fn v2(&mut self, a: &arg_qrr_e, op: u32, c: Chk) -> bool {
        let ok = chk(c, a.q, a.esz);
        self.emit(ok, &NEON, [a.rd, a.rn, 0, 0], Desc::new(op, a.esz, oprsz(a.q)))
    }

    pub(super) fn s2(&mut self, a: &arg_rr_e, op: u32) -> bool {
        self.emit(true, &NEON, [a.rd, a.rn, 0, 0], Desc::new(op, a.esz, 1 << a.esz))
    }

    /// The scalar forms that only have 64 bit elements.
    pub(super) fn s2d(&mut self, a: &arg_rr, op: u32) -> bool {
        self.emit(true, &NEON, [a.rd, a.rn, 0, 0], Desc::new(op, 3, 8))
    }

    /// Scalar pairwise: one result from the two elements of Rn.
    pub(super) fn sp(&mut self, a: &arg_rr_e, op: u32) -> bool {
        self.emit(true, &NEON, [a.rd, a.rn, a.rn, 0], Desc::new(op, a.esz, 1 << a.esz))
    }

    /// `do_int_reduction()`: at least four elements.
    pub(super) fn vred(&mut self, a: &arg_qrr_e, op: u32) -> bool {
        let ok = a.esz != 3 && (oprsz(a.q) >> a.esz) >= 4;
        self.emit(ok, &NEON, [a.rd, a.rn, 0, 0], Desc::new(op, a.esz, oprsz(a.q)))
    }

    /// The narrowing forms: the "2" forms (`q` set) write the high half and keep the low.
    pub(super) fn narrow_v(&mut self, a: &arg_qrr_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, oprsz(a.q)).hi(a.q != 0);
        self.emit(a.esz != 3, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn narrow_s(&mut self, a: &arg_rr_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 1 << a.esz);
        self.emit(a.esz != 3, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn shll(&mut self, a: &arg_qrr_e) -> bool {
        let desc = Desc::new(nop::SHLL, a.esz, 16).hi(a.q != 0);
        self.emit(a.esz != 3, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    // Shifts by immediate.

    pub(super) fn vsh(&mut self, a: &arg_qrri_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, oprsz(a.q)).imm(a.imm);
        self.emit(true, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn ssh(&mut self, a: &arg_rri_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 1 << a.esz).imm(a.imm);
        self.emit(true, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn vshn(&mut self, a: &arg_qrri_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, oprsz(a.q)).hi(a.q != 0).imm(a.imm);
        self.emit(true, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn vshll(&mut self, a: &arg_qrri_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 16).hi(a.q != 0).imm(a.imm);
        self.emit(true, &NEON, [a.rd, a.rn, 0, 0], desc)
    }

    // Widening, narrowing three registers and indexed.

    pub(super) fn wide(&mut self, a: &arg_qrrr_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 16).hi(a.q != 0);
        self.emit(a.esz < 3, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn pmull64(&mut self, a: &arg_qrrr_e) -> bool {
        let ok = self.has(Feat::Pmull);
        let desc = Desc::new(nop::PMULL, 3, 16).hi(a.q != 0);
        self.emit(ok, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn wide_vi(&mut self, a: &arg_qrrx_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 16).hi(a.q != 0).indexed(a.idx);
        self.emit(a.esz < 3, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn wide_si(&mut self, a: &arg_rrx_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 1 << a.esz).indexed(a.idx);
        self.emit(a.esz < 3, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn vi(&mut self, a: &arg_qrrx_e, op: u32, f: Feat) -> bool {
        let ok = self.has(f);
        let desc = Desc::new(op, a.esz, oprsz(a.q)).indexed(a.idx);
        self.emit(ok, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn si(&mut self, a: &arg_rrx_e, op: u32, f: Feat) -> bool {
        let ok = self.has(f) && chk(Chk::Hs, 1, a.esz);
        let desc = Desc::new(op, a.esz, 1 << a.esz).indexed(a.idx);
        self.emit(ok, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    // Permutes and tables.

    pub(super) fn ext(&mut self, a: &arg_crypto3i, q: bool) -> bool {
        let desc = Desc::new(nop::EXT, 0, if q { 16 } else { 8 }).imm(a.imm);
        self.emit(true, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn tbl(&mut self, a: &arg_disas_a6471) -> bool {
        let op = if a.tbx != 0 { nop::TBX } else { nop::TBL };
        let desc = Desc::new(op, 0, oprsz(a.q)).imm(a.len);
        self.emit(true, &NEON, [a.rd, a.rn, a.rm, 0], desc)
    }

    // Crypto.

    pub(super) fn cr3(&mut self, a: &arg_qrrr_e, op: u32, f: Feat) -> bool {
        let ok = self.has(f);
        let def = &crate::tcg::crypto::CRYPTO;
        self.emit(ok, def, [a.rd, a.rn, a.rm, 0], Desc::new(op, 0, 16))
    }

    pub(super) fn cr2(&mut self, a: &arg_qrr_e, op: u32, f: Feat) -> bool {
        let ok = self.has(f);
        let def = &crate::tcg::crypto::CRYPTO;
        self.emit(ok, def, [a.rd, a.rn, 0, 0], Desc::new(op, 0, 16))
    }

    /// AESE and AESD: the state is Rd and the key Rm.
    pub(super) fn aes(&mut self, a: &arg_qrrr_e, op: u32) -> bool {
        let ok = self.has(Feat::Aes);
        let def = &crate::tcg::crypto::CRYPTO;
        self.emit(ok, def, [a.rd, a.rm, 0, 0], Desc::new(op, 0, 16))
    }

    // Floating point data processing.

    pub(super) fn f3v(&mut self, a: &arg_qrrr_e, op: u32) -> bool {
        let ok = self.hsd(a.esz, a.q != 0);
        self.emit(ok, &FP, [a.rd, a.rn, a.rm, 0], Desc::new(op, a.esz, oprsz(a.q)))
    }

    pub(super) fn f3s(&mut self, a: &arg_rrr_e, op: u32) -> bool {
        let ok = self.hsd(a.esz, true);
        self.emit(ok, &FP, [a.rd, a.rn, a.rm, 0], Desc::new(op, a.esz, 1 << a.esz))
    }

    /// Scalar pairwise: one result from the two elements of Rn.
    pub(super) fn fps(&mut self, a: &arg_rr_e, op: u32) -> bool {
        let ok = self.hsd(a.esz, true);
        self.emit(ok, &FP, [a.rd, a.rn, a.rn, 0], Desc::new(op, a.esz, 1 << a.esz))
    }

    /// `do_fp_reduction()`; the half precision forms need FEAT_FP16.
    pub(super) fn fred(&mut self, a: &arg_qrr_e, op: u32) -> bool {
        let ok = a.esz != 1 || self.has(Feat::Fp16);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], Desc::new(op, a.esz, oprsz(a.q)))
    }

    pub(super) fn f2s(&mut self, a: &arg_rr_e, op: u32, rm: u32) -> bool {
        let ok = self.hsd(a.esz, true);
        let desc = Desc::new(op, a.esz, 1 << a.esz).rmode(rm);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn f2v(&mut self, a: &arg_qrr_e, op: u32, rm: u32) -> bool {
        let ok = self.hsd(a.esz, a.q != 0);
        let desc = Desc::new(op, a.esz, oprsz(a.q)).rmode(rm);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn fsi(&mut self, a: &arg_rrx_e, op: u32) -> bool {
        let ok = self.hsd(a.esz, true);
        let desc = Desc::new(op, a.esz, 1 << a.esz).indexed(a.idx);
        self.emit(ok, &FP, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn fvi(&mut self, a: &arg_qrrx_e, op: u32) -> bool {
        let ok = self.hsd(a.esz, a.q != 0);
        let desc = Desc::new(op, a.esz, oprsz(a.q)).indexed(a.idx);
        self.emit(ok, &FP, [a.rd, a.rn, a.rm, 0], desc)
    }

    pub(super) fn fmadd(&mut self, a: &arg_rrrr_e, op: u32) -> bool {
        let ok = self.hsd(a.esz, true);
        self.emit(ok, &FP, [a.rd, a.rn, a.rm, a.ra], Desc::new(op, a.esz, 1 << a.esz))
    }

    // Conversions.

    /// `do_fcvt_g()`: FP to a general register.
    pub(super) fn fcvt_g(&mut self, a: &arg_fcvt, signed: bool, rm: u32) -> bool {
        if !self.hsd(a.esz, true) {
            return false;
        }
        if self.fp_access_check() {
            let op = if signed { fop::TOSINT } else { fop::TOUINT };
            let desc = Desc::new(op, a.esz, 1 << a.esz).imm(a.shift).hi(a.sf != 0).rmode(rm);
            let x = self.c64(0);
            let ret = self.gpr_call(x, [0, a.rn, 0, 0], desc);
            self.set_reg(a.rd, ret);
        }
        true
    }

    /// `do_cvtf_g()`: a general register to FP.
    pub(super) fn cvtf_g(&mut self, a: &arg_fcvt, signed: bool) -> bool {
        if !self.hsd(a.esz, true) {
            return false;
        }
        if self.fp_access_check() {
            let op = if signed { fop::SCVTF } else { fop::UCVTF };
            let desc = Desc::new(op, a.esz, 1 << a.esz).imm(a.shift).hi(a.sf != 0);
            let x = self.reg(a.rn);
            self.gpr_call(x, [a.rd, 0, 0, 0], desc);
        }
        true
    }

    fn gpr_call(&mut self, x: TempI64, r: [i32; 4], desc: Desc) -> TempI64 {
        let env = self.env();
        let regs = self.c32(Regs::pack(r[0], r[1], r[2], r[3]) as i32);
        let d = self.c32(desc.pack() as i32);
        let ret = self.new64();
        self.call(&FP_GPR, Some(ret.into()), &[env.into(), x.into(), regs.into(), d.into()]);
        ret
    }

    /// `do_fcvt_f()`: FP to an integer of the same size in a SIMD register.
    pub(super) fn fcvt_f(&mut self, a: &arg_fcvt, signed: bool, rm: u32) -> bool {
        let ok = self.hsd(a.esz, true);
        let op = if signed { fop::TOSINT } else { fop::TOUINT };
        let desc = Desc::new(op, a.esz, 1 << a.esz).imm(a.shift).rmode(rm);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    /// `do_cvtf_f()`.
    pub(super) fn cvtf_f(&mut self, a: &arg_fcvt, signed: bool) -> bool {
        let ok = self.hsd(a.esz, true);
        let op = if signed { fop::SCVTF } else { fop::UCVTF };
        let desc = Desc::new(op, a.esz, 1 << a.esz).imm(a.shift);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    /// The vector fixed point forms: FCVTZS and FCVTZU round to zero.
    pub(super) fn cvt_vf(&mut self, a: &arg_fcvt_q, op: u32) -> bool {
        let ok = self.hsd(a.esz, a.q != 0);
        let rm = if op == fop::TOSINT || op == fop::TOUINT { RZ } else { RF };
        let desc = Desc::new(op, a.esz, oprsz(a.q)).imm(a.shift).rmode(rm);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    /// FCVT between precisions: `from` and `to` are element sizes.
    pub(super) fn fcvt_s(&mut self, a: &arg_rr, from: i32, to: i32) -> bool {
        let desc = Desc::new(fop::FCVT, from, 1 << from).imm(to);
        self.emit(true, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn fcvtl(&mut self, a: &arg_qrr_e) -> bool {
        let desc = Desc::new(fop::FCVTL, a.esz, 16).hi(a.q != 0);
        self.emit(true, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn fcvtn(&mut self, a: &arg_qrr_e, op: u32) -> bool {
        let desc = Desc::new(op, a.esz, 8).hi(a.q != 0);
        self.emit(a.esz != 3, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    pub(super) fn fcvtxn_s(&mut self, a: &arg_rr_e) -> bool {
        let desc = Desc::new(fop::FCVTXN, 2, 4);
        self.emit(true, &FP, [a.rd, a.rn, 0, 0], desc)
    }

    /// URECPE and URSQRTE: integer estimates on 32 bit elements.
    pub(super) fn urecpe(&mut self, a: &arg_qrr_e, op: u32) -> bool {
        let ok = chk(Chk::Fn, a.q, a.esz);
        self.emit(ok, &FP, [a.rd, a.rn, 0, 0], Desc::new(op, 2, oprsz(a.q)))
    }

    // Moves and immediates.

    pub(super) fn fmov_g(&mut self, a: &arg_rr, k: Mov) -> bool {
        if matches!(k, Mov::Hx | Mov::Xh) && !self.has(Feat::Fp16) {
            return false;
        }
        if !self.fp_access_check() {
            return true;
        }
        let rn_off = vreg_off(a.rn as usize);
        match k {
            Mov::Hx | Mov::Sw | Mov::Dx => {
                let t = self.reg(a.rn);
                match k {
                    Mov::Hx => self.f().gen_ext16u_i64(t, t),
                    Mov::Sw => self.f().gen_ext32u_i64(t, t),
                    _ => {}
                }
                self.write_fp_dreg(a.rd, t);
            }
            Mov::Ux => {
                let t = self.reg(a.rn);
                self.st_env64(t, vreg_off(a.rd as usize) + 8);
                self.clear_sve(a.rd);
            }
            Mov::Xh => {
                let t = self.read_elem(a.rn, 0, 1, false);
                self.set_reg(a.rd, t);
            }
            Mov::Ws => {
                let t = self.read_elem(a.rn, 0, 2, false);
                self.set_reg(a.rd, t);
            }
            Mov::Xd => {
                let t = self.ld_env64(rn_off);
                self.set_reg(a.rd, t);
            }
            Mov::Xu => {
                let t = self.ld_env64(rn_off + 8);
                self.set_reg(a.rd, t);
            }
        }
        true
    }

    pub(super) fn fcsel(&mut self, a: &arg_disas_a6470) -> bool {
        if !self.hsd(a.esz, true) {
            return false;
        }
        if self.fp_access_check() {
            let t_true = self.read_elem(a.rn, 0, a.esz, false);
            let t_false = self.read_elem(a.rm, 0, a.esz, false);
            let (cond, v) = self.test_cc64(a.cond);
            let zero = self.c64(0);
            self.f().gen_movcond_i64(cond, t_true, v, zero, t_true, t_false);
            self.write_fp_dreg(a.rd, t_true);
        }
        true
    }

    /// `gen_set_nzcv()`: NZCV from bits 31 to 28 of `t`.
    fn set_nzcv(&mut self, t: TempI32) {
        self.st_env32(t, NF);
        let z = self.new32();
        let c = self.new32();
        let v = self.new32();
        let f = self.f();
        f.gen_andi_i32(z, t, 0x4000_0000);
        f.gen_setcondi_i32(Cond::Eq, z, z, 0);
        f.gen_shri_i32(c, t, 29);
        f.gen_andi_i32(c, c, 1);
        f.gen_andi_i32(v, t, 0x1000_0000);
        f.gen_shli_i32(v, v, 3);
        self.st_env32(z, ZF);
        self.st_env32(c, CF);
        self.st_env32(v, VF);
    }

    /// `handle_fp_compare()`.
    fn fp_compare(&mut self, esz: i32, rn: i32, rm: i32, zero: bool, signal: bool) {
        let op = if signal { fop::CMPE } else { fop::CMP };
        let desc = Desc::new(op, esz, 1 << esz).imm(i32::from(zero));
        let env = self.env();
        let regs = self.c32(Regs::pack(0, rn, rm, 0) as i32);
        let d = self.c32(desc.pack() as i32);
        let ret = self.new32();
        self.call(&FP_CMP, Some(ret.into()), &[env.into(), regs.into(), d.into()]);
        self.set_nzcv(ret);
    }

    pub(super) fn fcmp(&mut self, a: &arg_disas_a6474) -> bool {
        if !self.hsd(a.esz, true) {
            return false;
        }
        if self.fp_access_check() {
            self.fp_compare(a.esz, a.rn, a.rm, a.z != 0, a.e != 0);
        }
        true
    }

    pub(super) fn fccmp(&mut self, a: &arg_disas_a6475) -> bool {
        if !self.hsd(a.esz, true) {
            return false;
        }
        if !self.fp_access_check() {
            return true;
        }
        let mut cont = None;
        if a.cond < 0xe {
            let matched = self.f().new_label();
            let l = self.f().new_label();
            let (cond, v) = self.test_cc(a.cond);
            self.f().gen_brcondi_i32(cond, v, 0, matched);
            let nzcv = self.c32(((a.nzcv as u32) << 28) as i32);
            self.set_nzcv(nzcv);
            self.f().gen_br(l);
            self.f().gen_set_label(matched);
            cont = Some(l);
        }
        self.fp_compare(a.esz, a.rn, a.rm, false, a.e != 0);
        if let Some(l) = cont {
            self.f().gen_set_label(l);
        }
        true
    }

    pub(super) fn fmovi_s(&mut self, a: &arg_disas_a6473) -> bool {
        if !self.hsd(a.esz, true) {
            return false;
        }
        if self.fp_access_check() {
            let imm = vfp_expand_imm(a.esz as u32, a.imm as u32);
            let t = self.c64(imm as i64);
            self.write_fp_dreg(a.rd, t);
        }
        true
    }

    pub(super) fn fmovi_vh(&mut self, a: &arg_disas_a6476) -> bool {
        if !self.has(Feat::Fp16) {
            return false;
        }
        if self.fp_access_check() {
            let imm = dup_const(1, vfp_expand_imm(1, a.abcdefgh as u32));
            let t = self.c64(imm as i64);
            self.write_dup(a.rd, t, a.q != 0);
        }
        true
    }

    /// `trans_Vimm()`: MOVI, MVNI, ORR, BIC and FMOV (vector, immediate).
    pub(super) fn vimm(&mut self, a: &arg_disas_a6477) -> bool {
        let logic = (a.cmode & 1) != 0 && a.cmode < 12;
        if !logic && a.cmode == 15 && a.op == 1 && a.q == 0 {
            return false;
        }
        if !self.fp_access_check() {
            return true;
        }
        let imm = asimd_imm_const(a.abcdefgh as u32, a.cmode, a.op);
        if logic {
            let off = vreg_off(a.rd as usize);
            let lo = self.ld_env64(off);
            let hi = if a.q != 0 { Some(self.ld_env64(off + 8)) } else { None };
            for t in [Some(lo), hi].into_iter().flatten() {
                if a.op != 0 {
                    self.f().gen_andi_i64(t, t, imm as i64);
                } else {
                    self.f().gen_ori_i64(t, t, imm as i64);
                }
            }
            self.write_vreg(a.rd, lo, hi);
        } else {
            let t = self.c64(imm as i64);
            self.write_dup(a.rd, t, a.q != 0);
        }
        true
    }

    // Copies between elements and registers.

    pub(super) fn dup_s(&mut self, a: &arg_disas_a6465) -> bool {
        let Some((esz, idx)) = decode_esz_idx(a.imm) else {
            return false;
        };
        if self.fp_access_check() {
            let t = self.read_elem(a.rn, idx, esz, false);
            self.write_fp_dreg(a.rd, t);
        }
        true
    }

    pub(super) fn dup_v(&mut self, a: &arg_disas_a6466) -> bool {
        let Some((esz, idx)) = decode_esz_idx(a.imm) else {
            return false;
        };
        if esz == 3 && a.q == 0 {
            return false;
        }
        if self.fp_access_check() {
            let t = self.read_elem(a.rn, idx, esz, false);
            self.dup64(t, esz);
            self.write_dup(a.rd, t, a.q != 0);
        }
        true
    }

    pub(super) fn dup_g(&mut self, a: &arg_disas_a6466) -> bool {
        let Some((esz, _)) = decode_esz_idx(a.imm) else {
            return false;
        };
        if esz == 3 && a.q == 0 {
            return false;
        }
        if self.fp_access_check() {
            let t = self.reg(a.rn);
            self.dup64(t, esz);
            self.write_dup(a.rd, t, a.q != 0);
        }
        true
    }

    pub(super) fn ins_g(&mut self, a: &arg_disas_a6465) -> bool {
        let Some((esz, idx)) = decode_esz_idx(a.imm) else {
            return false;
        };
        if self.fp_access_check() {
            let t = self.reg(a.rn);
            self.write_elem(a.rd, idx, esz, t);
            self.clear_sve(a.rd);
        }
        true
    }

    pub(super) fn ins_e(&mut self, a: &arg_disas_a6467) -> bool {
        let Some((esz, didx)) = decode_esz_idx(a.di) else {
            return false;
        };
        let sidx = a.si >> esz;
        if self.fp_access_check() {
            let t = self.read_elem(a.rn, sidx, esz, false);
            self.write_elem(a.rd, didx, esz, t);
            self.clear_sve(a.rd);
        }
        true
    }

    /// `do_smov_umov()`.
    pub(super) fn smov_umov(&mut self, a: &arg_disas_a6466, signed: bool) -> bool {
        let Some((esz, idx)) = decode_esz_idx(a.imm) else {
            return false;
        };
        let bad = if signed {
            esz == 3 || (esz == 2 && a.q == 0)
        } else if esz == 3 {
            a.q == 0
        } else {
            a.q != 0
        };
        if bad {
            return false;
        }
        if self.fp_access_check() {
            let t = self.read_elem(a.rn, idx, esz, signed);
            if signed && a.q == 0 {
                self.f().gen_ext32u_i64(t, t);
            }
            self.set_reg(a.rd, t);
        }
        true
    }

    // Loads and stores.

    /// `finalize_memop_asimd()`.
    fn memop_asimd(&self, sz: i32) -> MemOp {
        if sz == 4 {
            self.finalize_memop_atom(MemOp(4), MemOp::ATOM_IFALIGN_PAIR)
        } else {
            self.finalize_memop(MemOp(sz as u32))
        }
    }

    /// `do_fp_ld()`: load into the low bits of `rt`, clearing the rest.
    fn fp_ld(&mut self, rt: i32, addr: TempI64, mop: MemOp) {
        let idx = self.get_mem_index();
        let lo = self.new64();
        if mop.0 & MemOp::SIZE.0 < 4 {
            self.f().gen_qemu_ld_i64(lo, addr, idx, mop);
            self.write_vreg(rt, lo, None);
        } else {
            let hi = self.new64();
            let f = self.f();
            let t = f.temp_new_i128();
            f.gen_qemu_ld_i128(t, addr, idx, mop);
            f.gen_extr_i128_i64(lo, hi, t);
            self.write_vreg(rt, lo, Some(hi));
        }
    }

    /// `do_fp_st()`: store the low bits of `rt`.
    fn fp_st(&mut self, rt: i32, addr: TempI64, mop: MemOp) {
        let idx = self.get_mem_index();
        let off = vreg_off(rt as usize);
        let lo = self.ld_env64(off);
        if mop.0 & MemOp::SIZE.0 < 4 {
            self.f().gen_qemu_st_i64(lo, addr, idx, mop);
        } else {
            let hi = self.ld_env64(off + 8);
            let f = self.f();
            let t = f.temp_new_i128();
            f.gen_concat_i64_i128(t, lo, hi);
            f.gen_qemu_st_i128(t, addr, idx, mop);
        }
    }

    fn fp_ldst(&mut self, is_load: bool, rt: i32, addr: TempI64, mop: MemOp) {
        if is_load {
            self.fp_ld(rt, addr, mop);
        } else {
            self.fp_st(rt, addr, mop);
        }
    }

    pub(super) fn ld_lit_v(&mut self, a: &arg_ldlit) -> bool {
        if self.fp_access_check() {
            let mop = self.memop_asimd(a.sz);
            let addr = self.c64(self.d.pc_curr.wrapping_add(i64::from(a.imm) as u64) as i64);
            self.fp_ld(a.rt, addr, mop);
        }
        true
    }

    pub(super) fn ldst_v_i(&mut self, a: &arg_ldst_imm, is_load: bool) -> bool {
        if self.fp_access_check() {
            let mop = self.memop_asimd(a.sz);
            let imm = i64::from(a.imm);
            let (dirty, clean) = self.addr_imm_pre(a.rn, imm, a.p != 0);
            self.fp_ldst(is_load, a.rt, clean, mop);
            self.addr_imm_post(a.rn, dirty, imm, a.w != 0, a.p != 0);
        }
        true
    }

    pub(super) fn ldst_v(&mut self, a: &arg_ldst, is_load: bool) -> bool {
        if a.opt & 2 == 0 {
            return false;
        }
        if self.fp_access_check() {
            let mop = self.memop_asimd(a.sz);
            let clean = self.addr_reg(a);
            self.fp_ldst(is_load, a.rt, clean, mop);
        }
        true
    }

    pub(super) fn ldstp_v(&mut self, a: &arg_ldstpair, is_load: bool) -> bool {
        if self.fp_access_check() {
            let offset = i64::from(a.imm) << a.sz;
            let mop = self.memop_asimd(a.sz);
            let (dirty, clean) = self.addr_imm_pre(a.rn, offset, a.p != 0);
            self.fp_ldst(is_load, a.rt, clean, mop);
            self.f().gen_addi_i64(clean, clean, 1 << a.sz);
            self.fp_ldst(is_load, a.rt2, clean, mop);
            self.addr_imm_post(a.rn, dirty, offset, a.w != 0, a.p != 0);
        }
        true
    }

    /// `do_vec_ld()` and `do_vec_st()`: one element.
    fn vec_ldst(&mut self, is_load: bool, reg: i32, e: i32, addr: TempI64, mop: MemOp) {
        let idx = self.get_mem_index();
        let esz = (mop.0 & MemOp::SIZE.0) as i32;
        if is_load {
            let t = self.new64();
            self.f().gen_qemu_ld_i64(t, addr, idx, mop);
            self.write_elem(reg, e, esz, t);
        } else {
            let t = self.read_elem(reg, e, esz, false);
            self.f().gen_qemu_st_i64(t, addr, idx, mop);
        }
    }

    /// The post-index writeback of the structure loads and stores.
    fn ldst_writeback(&mut self, rn: i32, base: TempI64, p: i32, rm: i32, total: i32) {
        if p == 0 {
            return;
        }
        if rm == 31 {
            self.f().gen_addi_i64(base, base, i64::from(total));
        } else {
            let m = self.reg(rm);
            self.f().gen_add_i64(base, base, m);
        }
        self.set_reg_sp(rn, base);
    }

    /// `trans_LD_mult()` and `trans_ST_mult()`.
    pub(super) fn ldst_mult(&mut self, a: &arg_ldst_mult, is_load: bool) -> bool {
        if a.p == 0 && a.rm != 0 {
            return false;
        }
        if a.sz == 3 && a.q == 0 && a.selem != 1 {
            return false;
        }
        if !self.fp_access_check() {
            return true;
        }
        let total = a.rpt * a.selem * oprsz(a.q) as i32;
        let base = self.reg_sp(a.rn);
        let clean = self.clean_data_tbi(base);
        // Consecutive little endian elements from one register are loaded 64 bits at a time.
        let mut size = a.sz;
        let mut align = MemOp::ALIGN;
        if a.selem == 1 {
            align = MemOp((size as u32) << 5);
            size = 3;
        }
        if !self.d.align_mem {
            align = MemOp(0);
        }
        let mop = MemOp(size as u32) | align | MemOp::LE;
        let elements = oprsz(a.q) as i32 >> size;
        for r in 0..a.rpt {
            for e in 0..elements {
                for xs in 0..a.selem {
                    let tt = (a.rt + r + xs) % 32;
                    self.vec_ldst(is_load, tt, e, clean, mop);
                    self.f().gen_addi_i64(clean, clean, 1 << size);
                }
            }
        }
        if is_load {
            for r in 0..a.rpt * a.selem {
                if a.q == 0 {
                    self.clear_high((a.rt + r) % 32);
                } else {
                    self.clear_sve((a.rt + r) % 32);
                }
            }
        }
        self.ldst_writeback(a.rn, base, a.p, a.rm, total);
        true
    }

    /// `trans_LD_single()` and `trans_ST_single()`.
    pub(super) fn ldst_single(&mut self, a: &arg_ldst_single, is_load: bool) -> bool {
        if a.p == 0 && a.rm != 0 {
            return false;
        }
        if !self.fp_access_check() {
            return true;
        }
        let total = a.selem << a.scale;
        let base = self.reg_sp(a.rn);
        let mop = self.memop_asimd(a.scale);
        let clean = self.clean_data_tbi(base);
        for xs in 0..a.selem {
            let rt = (a.rt + xs) % 32;
            self.vec_ldst(is_load, rt, a.index, clean, mop);
            self.f().gen_addi_i64(clean, clean, 1 << a.scale);
        }
        self.ldst_writeback(a.rn, base, a.p, a.rm, total);
        true
    }

    /// `trans_LD_single_repl()`.
    pub(super) fn ld_repl(&mut self, a: &arg_disas_a6452) -> bool {
        if a.p == 0 && a.rm != 0 {
            return false;
        }
        if !self.fp_access_check() {
            return true;
        }
        let total = a.selem << a.scale;
        let base = self.reg_sp(a.rn);
        let mop = self.memop_asimd(a.scale);
        let clean = self.clean_data_tbi(base);
        let idx = self.get_mem_index();
        for xs in 0..a.selem {
            let rt = (a.rt + xs) % 32;
            let t = self.new64();
            self.f().gen_qemu_ld_i64(t, clean, idx, mop);
            self.dup64(t, a.scale);
            self.write_dup(rt, t, a.q != 0);
            self.f().gen_addi_i64(clean, clean, 1 << a.scale);
        }
        self.ldst_writeback(a.rn, base, a.p, a.rm, total);
        true
    }
}

