pub(super) use simd_trans;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn imm_const() {
        // MOVI Vd.4S, #0xab, LSL #8.
        assert_eq!(asimd_imm_const(0xab, 2, 0), 0x0000_ab00_0000_ab00);
        // MVNI: inverted.
        assert_eq!(asimd_imm_const(0xab, 2, 1), 0xffff_54ff_ffff_54ff);
        // MOVI Dd, #mask.
        assert_eq!(asimd_imm_const(0x81, 14, 1), 0xff00_0000_0000_00ff);
        // FMOV Vd.2D, #1.0.
        assert_eq!(asimd_imm_const(0x70, 15, 1), 0x3ff0_0000_0000_0000);
        // FMOV Vd.4S, #1.0.
        assert_eq!(asimd_imm_const(0x70, 15, 0), 0x3f80_0000_3f80_0000);
        assert_eq!(dup_const(1, 0x3c00), 0x3c00_3c00_3c00_3c00);
        assert_eq!(decode_esz_idx(0b10110), Some((1, 0b101)));
        assert_eq!(decode_esz_idx(0), None);
    }
}
